import { MathRandomType } from './types';

export { };
function defineArrayProperty<T>(name: string, value: T, guard = false) {
    if (guard && name in Array.prototype) return;
    Object.defineProperty(Array.prototype, name, {
        value, enumerable: false, configurable: true, writable: true,
    });
}

const randomRangeAsInt = (min: number, max: number, rng: MathRandomType) => {
    return Math.getRandomRange(min, max, true, rng);
};

function getRandom<T>(this: T[], rng: MathRandomType = Math.random) {
    return this[randomRangeAsInt(0, this.length - 1, rng)];
}
function shuffle<T>(this: T[], makeCopy: boolean = true, rng: MathRandomType = Math.random) {
    return Array.shuffle(makeCopy ? [...this] : this, rng);
}
function wrappingIndex<T>(this: T[], index: number) {
    return this[index.mod(this.length)];
}
function isSorted<T>(this: T[], compareFn = (a: T, b: T) => a <= b) {
    for (let i = 1; i < this.length; i++) {
        if (!compareFn(this[i - 1], this[i])) return false;
    }
    return true;
}
function isEqualTo<T>(this: T[], arr: T[]) {
    if (this.length !== arr.length) return false;

    for (let i = 0; i < this.length; i++) {
        if (this[i] !== arr[i]) return false;
    }
    return true;
}
function indexPreservingSort<T>(this: T[], compareFn: (a: T, b: T) => number = (a: any, b: any) => a - b): T[] {
    const sorted = [...this].sort(compareFn);
    const needsSorting: T[] = [];
    const indexes: number[] = [];

    this.forEach((val, i) => compareFn(val, sorted[i]) && needsSorting.push(val) && indexes.push(i));
    needsSorting.sort(compareFn).forEach((val, i) => this[indexes[i]] = val);
    return this;
}
function remove<T>(this: T[], item: T) {
    const index = this.indexOf(item);
    if (index > -1) this.splice(index, 1);
}
function sortAscending<T>(this: T[]) {
    return this.sort(Math.sortAscending);
}
function sortDescending<T>(this: T[]) {
    return this.sort(Math.sortDescending);
}

defineArrayProperty('getRandom', getRandom, true);
defineArrayProperty('shuffle', shuffle, true);
defineArrayProperty('wrappingIndex', wrappingIndex);
defineArrayProperty('isSorted', isSorted);
defineArrayProperty('isEqualTo', isEqualTo);
defineArrayProperty('indexPreservingSort', indexPreservingSort);
defineArrayProperty('remove', remove);
defineArrayProperty('sortAscending', sortAscending);
defineArrayProperty('sortDescending', sortDescending);

Array.shuffle = function <T>(arr: T[], rng: MathRandomType = Math.random) {
    let randomIndex;
    let tempValue;
    let index;
    for (index = arr.length - 1; index > 0; --index) {
        randomIndex = randomRangeAsInt(0, index, rng);
        tempValue = arr[index];
        arr[index] = arr[randomIndex];
        arr[randomIndex] = tempValue;
    }
    return arr;
};

Array.fromLength = function <U>(length: number, mapfn: (i: number, length: number) => U): U[] {
    return Array.from({ length }, (_, i) => mapfn(i, length));
};

Array.callBetween = function <U>(length: number, callfn: (i: number, length: number) => void, mapfn: (i: number, length: number) => U): U[] {
    return Array.fromLength(length, (i) => {
        if (i) callfn(i, length);
        return mapfn(i, length);
    });
};

Array.callAround = function <U>(length: number, callfn: (i: number, length: number) => void, mapfn: (i: number, length: number) => U): U[] {
    callfn(0, length);
    return Array.fromLength(length, (i) => {
        const element = mapfn(i, length);
        callfn(i + 1, length);
        return element;
    });
};

declare global {
    // tslint:disable-next-line:interface-name
    interface Array<T> {
        getRandom: typeof getRandom<T>;
        shuffle: typeof shuffle<T>;
        wrappingIndex: typeof wrappingIndex<T>;
        isSorted: typeof isSorted<T>;
        isEqualTo: typeof isEqualTo<T>;
        indexPreservingSort: typeof indexPreservingSort<T>
        remove: typeof remove<T>;
        sortAscending: typeof sortAscending<T>;
        sortDescending: typeof sortDescending<T>;
    }

    interface ArrayConstructor {
        fromLength<U>(length: number, mapfn: (i: number, length: number) => U): U[];
        callBetween<U>(length: number, callfn: (i: number, length: number) => void, mapfn: (i: number, length: number) => U): U[];
        callAround<U>(length: number, callfn: (i: number, length: number) => void, mapfn: (i: number, length: number) => U): U[];
        shuffle<T>(arr: T[], rng?: MathRandomType): T[];
    }
}